mapper.select:

        /* isry.cysns.casemng.casereg.mapper.selectReqById - Hee Sung Yoon */
        SELECT A.CASE_MNG_NO
		    , A.CASE_MNG_ODRNO
		    , A.CRISIS_SCRENN_SCORE_SE_CD
		    , A.CRISIS_SCRENN_EVL_SCORE
		FROM ACA130 A
		WHERE CASE_MNG_NO = #{CASE_MNG_NO}
		AND CASE_MNG_ODRNO = #{CASE_MNG_ODRNO}


        /* isry.cysns.casemng.casereg.mapper.getTrprInfoNo - Hee Sung Yoon */
        SELECT A.TRPR_INFO_NO,
		    DECODE(B.DGNSS_EXMN_MNG_NO, NULL, C.DGNSS_EXMN_MNG_NO, B.DGNSS_EXMN_MNG_NO) AS DGNSS_EXMN_MNG_NO
		FROM SEB100 A, ACA210 B, ACA400 C
		WHERE A.CASE_MNG_NO = #{CASE_MNG_NO}
		  AND A.CASE_MNG_ODRNO = #{CASE_MNG_ODRNO}
		  AND A.TRPR_INFO_NO = B.TRPR_INFO_NO(+)
		  AND A.TRPR_INFO_NO = C.TRPR_INFO_NO(+)


/* selectGradeSttsByTrprInfoNo - Lee MS */

SELECT MAX(NVL(A.ACBG_SE_CD, '00')|| NVL(A.GRADE_SE_CD, '00')) AS ACBG_GRADE
  FROM SEA230 A
 WHERE A.TRPR_INFO_NO = #{TRPR_INFO_NO}


 /* selectSrvyTrprById - Lee  MS */

SELECT A.QUSTNB_MNG_NO
FROM SBB110 A /* 설문대상자 */
WHERE A.CASE_MNG_NO = #{CASE_MNG_NO}
  AND A.CASE_MNG_ODRNO = #{CASE_MNG_ODRNO}
  AND A.QUSTNB_SHAPE_SE_CD = #{QUSTNB_SHAPE_SE_CD}
  AND ROWNUM < 2


 /* selectSrvyTrprById - Lee  MS */

SELECT A.QUSTNB_MNG_NO
FROM SBB110 A /* 설문대상자 */
WHERE A.QUSTNB_TMPT_MNG_NO = #{QUSTNB_TMPT_MNG_NO}
  AND A.CASE_MNG_NO = #{CASE_MNG_NO}
  AND A.CASE_MNG_ODRNO = #{CASE_MNG_ODRNO}

mapper.delete:

 /* deleteExcnData2 - Lee  MS */

DELETE FROM ACA220 /* 치료지원 */
WHERE CASE_MNG_NO = #{CASE_MNG_NO}
  AND CASE_MNG_ODRNO = #{CASE_MNG_ODRNO}
  AND MDLRT_SN = #{MDLRT_SN}

mapper.select:

/* selectTrlInspByRecrceNo - Lee MS */
SELECT A.SRVC_RESRCE_MLSFC_SE_CD AS SRVC_RESRCE_MLSFC_SE_CD,    /* 제공서비스자원중분류구분코드 */
       A.SRVC_RESRCE_SCLAS_SE_CD AS SRVC_RESRCE_SCLAS_SE_CD     /* 제공서비스소분류구분코드 */
  FROM SDA100 A /* 자원기본 */
 WHERE A.RESRCE_NO = #{RESRCE_NO}
 AND A.SRVC_RESRCE_MLSFC_SE_CD = '0104'  /* 심리검사 */

mapper.delete:

 /* deleteTrlInspData - Lee  MS */

DELETE FROM ACA100 /* 심리검사결과 */
WHERE TRL_INSP_MNG_NO = #{TRL_INSP_MNG_NO}


 /* deleteTrlInspDtlData - Lee  MS */

DELETE FROM ACA110 /* 심리검사결과상세 */
WHERE TRL_INSP_MNG_NO = #{TRL_INSP_MNG_NO}

